/**
 * FlowStage
 * ---------
 * Inline stage marker placed in the flow body.
 * Each call marks the start of a new stage; all action instances that follow
 * (until the next stage marker or end of flow) belong to this stage.
 *
 * The resulting `sys_hub_flow_stage` record is attached to the parent flow.
 * `component_indexes` and `order` are computed automatically at build time —
 * the developer never needs to specify them.
 */
import type { Duration } from '../../db'

export type FlowStageStates = {
    /** Label shown when the stage has not yet started. */
    pending?: string
    /** Label shown while the stage is executing. */
    inProgress?: string
    /** Label shown when the stage finishes successfully. */
    complete?: string
    /** Label shown when the stage encounters an error. */
    error?: string
    /** Label shown when the stage is skipped. */
    skipped?: string
}

export type FlowStageConfig = {
    /** Display label shown in flow execution details. */
    label: string
    /** Internal identifier for this stage. Used as the coalesce key alongside the parent flow. */
    value: string
    /**
     * Expected duration for this stage, using the standard `Duration` type.
     * Stored as an offset from 1970-01-01 00:00:00 UTC.
     * Defaults to zero duration when omitted (the stage tracker uses the platform's display default).
     *
     * @example `Duration({ days: 1, hours: 4 })` → 1 day and 4 hours
     */
    duration?: Duration
    /** When true, this stage always appears in execution details even when not active. Defaults to false. */
    alwaysShow?: boolean
    /** Custom display labels for each execution state. Platform defaults are used for any omitted state. */
    states?: FlowStageStates
}

/**
 * Declares a stage definition for use in the `stages` header of a Flow or Subflow config.
 * The returned config is passed to `wfa.stage()` in the flow body via `params.stages.<key>`.
 *
 * @example
 * ```ts
 * Flow({
 *     name: 'Approval Flow',
 *     stages: {
 *         review:  FlowStage({ label: 'Review',  value: 'review',  duration: Duration({ days: 2 }) }),
 *         closure: FlowStage({ label: 'Closure', value: 'closure' }),
 *     },
 * }, trigger, ({ stages }) => {
 *     wfa.stage(stages.review)
 *     wfa.action(askForApproval, ...)
 *     wfa.stage(stages.closure)
 *     wfa.action(logResult, ...)
 * })
 * ```
 * @group Flow
 */
export function FlowStage(config: FlowStageConfig): FlowStageConfig {
    return config
}

/**
 * Marks the start of a stage boundary in the flow body.
 * Pass a stage declared in the `stages` config header via `params.stages.<key>`.
 *
 * ```ts
 * wfa.stage(params.stages.review)
 * ```
 *
 * All action instances that follow (until the next `wfa.stage()` call or end of flow) belong to this stage.
 * @group Flow
 */
export function Stage(_config: FlowStageConfig): void {}
